return {["scripts/actions/spells/blue/zephyr_mantle.lua"]={["Path"]="scripts/actions/spells/blue/zephyr_mantle.lua",["SHA256"]="435f593110c3efe26181719e86320aaa7c0f9e0eef3f4129a069a5c6337ce503",["Text"]="-----------------------------------\n-- Spell: Zephyr Mantle\n-- Creates shadow images that each absorb a single attack directed at you\n-- Spell cost: 31 MP\n-- Monster Type: Dragons\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 2\n-- Stat Bonus: AGI+2\n-- Level: 65\n-- Casting Time: 7 seconds\n-- Recast Time: 60 seconds\n-- Duration: 5 minutes\n-----------------------------------\n-- Combos: Conserve MP\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power    = 4\n    local tick     = 0\n    local duration = xi.spells.blue.calculateDurationWithDiffusion(caster, 300)\n\n    if not target:addStatusEffect(xi.effect.BLINK, { power = power, duration = duration, origin = caster, tick = tick }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.BLINK\nend\n\nreturn spellObject\n"},["scripts/actions/spells/geomancy/geo-acumen.lua"]={["Path"]="scripts/actions/spells/geomancy/geo-acumen.lua",["SHA256"]="cdad8477dbb08f698f574562e701f540e26aff63873da33e654031a8f936e9f8",["Text"]="-----------------------------------\n-- Spell: Geo-Acumen\n-- Enhances magic attack for party members within area of effect.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.job_utils.geomancer.geoOnMagicCastingCheck(caster, target, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    xi.job_utils.geomancer.spawnLuopan(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/geomancy/geo-agi.lua"]={["Pa